	entries := initLibraryEntries()
	entries["deploy-component/template.yaml"] = strings.Replace(initComponentTemplateYAML, "  files:\n", `  files:
    - path: overlays/local/kustomization.yaml.tmpl
      when: '{{ eq .env "local" }}'
    - path: overlays/local/fixtures/sftp.yaml.tmpl
      when: '{{- $recorded := dig "local" "bindings" dict . -}}{{- range .topology.connectors }}{{- $binding := default (get $recorded .name) (dig "binding" "" .) -}}{{- if eq $binding "sftp" }}true{{- end }}{{- end }}'
    - path: overlays/local/fixtures/http.yaml.tmpl
      when: '{{- $recorded := dig "local" "bindings" dict . -}}{{- range .topology.connectors }}{{- $binding := default (get $recorded .name) (dig "binding" "" .) -}}{{- if eq $binding "http" }}true{{- end }}{{- end }}'
    - path: overlays/local/fixtures/file.yaml.tmpl
      when: '{{- $recorded := dig "local" "bindings" dict . -}}{{- range .topology.connectors }}{{- $binding := default (get $recorded .name) (dig "binding" "" .) -}}{{- if eq $binding "file" }}true{{- end }}{{- end }}'
`, 1)
	entries["deploy-component/skeleton/overlays/local/kustomization.yaml.tmpl"] = `resources:
  - ../../base
`
	for _, fixture := range []string{"sftp", "http", "file"} {
		entries["deploy-component/skeleton/overlays/local/fixtures/"+fixture+".yaml.tmpl"] = `{{- range .topology.connectors }}
binding: {{ dig "binding" "" . }}
{{- end }}
`
	}
	f := newInitFixtureWith(t, entries)

	if _, _, err := runInit(t, f.options(nil, nil)); err != nil {
		t.Fatalf("manifest create: %v", err)
	}

	work := f.clone(t, "manifests-create/sales-distribution-all")
	fixtures := filepath.Join(work, "domains", "sales", "distribution", "extractor", "overlays", "local", "fixtures")
	for _, fixture := range []string{"sftp", "http"} {
		got, err := os.ReadFile(filepath.Join(fixtures, fixture+".yaml"))
		if err != nil {
			t.Errorf("read %s fixture: %v", fixture, err)
			continue
		}
		if !strings.Contains(string(got), "binding: "+fixture) {
			t.Errorf("%s fixture should receive the selected binding:\n%s", fixture, got)
		}
	}
	if _, err := os.Stat(filepath.Join(fixtures, "file.yaml")); !os.IsNotExist(err) {
		t.Errorf("unchosen file fixture = %v, want it absent", err)
	}
}

